\label{prop:orbit}
There are universal comparison constants such that
\begin{equation}\label{eq:orbit}
 S(\Omega)\asymp\mathcal H(\Omega).
\end{equation}
For every $a_0\in\Omega$,
\begin{align}
 \mathbb E\max_{a\in\Omega}\lvert \langle a-a_0,\varepsilon\rangle\rvert
   &\asymp\mathcal H(\Omega),\label{eq:anchor}\\
 S_{\mathrm{abs}}(\Omega)
   &\asymp\lVert a_0\rVert_2+\mathcal H(\Omega).\label{eq:absolute}
\end{align}
These statements include singleton orbits: then $\mathcal H(\Omega)=S(\Omega)=0$, while the absolute supremum is comparable to $\lVert a_0\rVert_2$.

\label{lem:gibbs}
For every $t>0$,
\begin{equation}\label{eq:haar}
 \operatorname{RD}^\chi_\lambda(t)=-\log Z_\Omega(t).
\end{equation}
The minimizing self-coupling is
\begin{equation}\label{eq:gibbs}
 Q_t(a,b)=\frac{\lambda(a)\lambda(b)e^{-D_t(a,b)}}{Z_\Omega(t)}.
\end{equation}

\label{thm:dyadic}
With constants depending only on $r$,
\begin{equation}\label{eq:dyadic}
 \mathcal H(\Omega)\asymp_r\sum_{n\ge0}2^n r^{-j_n^\lambda}.
\end{equation}
Consequently the sum in \eqref{eq:dyadic} estimates the signed supremum and the anchored absolute supremum. The unanchored absolute supremum has the additional term $\lVert a_0\rVert_2$.

\label{lem:laplace}
For every non-singleton orbit,
\begin{equation}\label{eq:laplace}
 \int_0^\infty F(t)\,dt\asymp\Delta+\sum_{n\ge1}2^n\tau_n.
\end{equation}

For $\tau_n>0$, the admissible set in \eqref{eq:tau} is $[\tau_n,\infty)$. This follows from continuity of each $D_t(a,b)$ and finiteness of the orbit. Comparing with the grid $t=r^{-j}$ gives
\begin{equation}\label{eq:grid}
 \tau_n\le r^{-j_n^\lambda}<r\tau_n\qquad(n\ge1).
\end{equation}
When $\tau_n=0$, all positive scales are admissible and both sides of the comparison vanish.

It remains to identify level zero. Vectors in a permutation orbit have the same coordinate sum, so two distinct vectors cannot differ in only one coordinate. If $D_t(a,b)\le1$ and $a\ne b$, no coordinate contribution can equal~$1$: otherwise all other differences would have to vanish. Thus no clipping occurs and $\lVert a-b\rVert_2\le t$. The converse is immediate. Transitivity makes the largest distance from a fixed point equal to $\Delta$, and consequently
\begin{equation}\label{eq:level-zero}
 \max_{b\in\Omega}D_t(a,b)\le1
 \quad\Longleftrightarrow\quad t\ge\Delta.
\end{equation}
For $\Delta>0$, this gives $\Delta\le r^{-j_0^\lambda}<r\Delta$. Now combine \eqref{eq:grid} with Lemma~\ref{lem:laplace}. For a singleton orbit, every $j_n^\lambda=\infty$ and both sides of \eqref{eq:dyadic} are zero.

\label{cor:overlap}
For $\mathbf 1_{\mathcal A}=\{\mathbf 1_B:B\in\mathcal A\}$, put
\[
 H_A=\mathcal L_A(1)+\frac12\int_0^1\mathcal L_A(s)s^{-3/2}\,ds.
\]
Then, with universal constants,
\begin{align}
 \mathbb E\max_{B\in\mathcal A}\sum_{i\in B}\varepsilon_i&\asymp H_A,\label{eq:overlap-signed}\\
 \mathbb E\max_{B\in\mathcal A}\left|\sum_{i\in B}\varepsilon_i\right|
   &\asymp\sqrt m+H_A.\label{eq:overlap}
\end{align}

\label{lem:scalar}
For $M\ge2$ and $v\ge0$, set
$q_M(v)=-\log[M^{-1}+(1-M^{-1})e^{-v}]$. Then
\begin{equation}\label{eq:scalar}
 \tfrac13\min\{v,\log M\}\le q_M(v)\le\min\{v,\log M\}.
\end{equation}
Moreover, for $a,L>0$,
\begin{equation}\label{eq:scalar-integral}
 \int_0^\infty\min\{a\chi(1/t),L\}\,dt
 =2\min\{a,\sqrt{aL}\}.
\end{equation}

\label{cor:separated}
Suppose $m\ge1$, $M=\lvert \mathcal A\rvert\ge2$, and $0<\delta\le1$. If
\begin{equation}\label{eq:sep}
 \lvert B\cap C\rvert\le(1-\delta)m
 \qquad(B,C\in\mathcal A,\ B\ne C),
\end{equation}
then
\begin{equation}\label{eq:sep-bound}
 \mathbb E\max_{B\in\mathcal A}\left|\sum_{i\in B}\varepsilon_i\right|
 \asymp_\delta\min\{m,\sqrt{m\log M}\}.
\end{equation}
The same estimate holds without absolute values.

\label{lem:integration}
For $m>0$, $L\ge1$, and $d\ge1$,
\begin{equation}\label{eq:integration}
 \int_0^\infty\min\!\left\{\frac m{t^2},\,
 L+d\log\!\left(1+\frac m{t^2}\right)\right\}\,dt
 \le C_d\sqrt{mL}.
\end{equation}

\label{thm:interval}
Uniformly in $N$ and $m$,
\begin{equation}\label{eq:interval}
 \mathbb E\max_{0\le k<N}\lvert W_{k,m}\rvert
 \asymp\min\!\left\{m,\sqrt{m\log\frac{eN}{m}}\right\}.
\end{equation}
For the signed maximum, put $u=\min\{m,N-m\}$. If $u\ge1$, then
\begin{equation}\label{eq:interval-signed}
 \mathbb E\max_{0\le k<N}W_{k,m}
 \asymp\min\!\left\{u,\sqrt{u\log\frac{eN}{u}}\right\}.
\end{equation}
If $m=N$, the signed expectation is zero.

\label{thm:boxes}
With constants depending only on $d$,
\begin{equation}\label{eq:boxes}
 \mathbb E\max_{g\in G}\left|\sum_{x\in g+A}\varepsilon_x\right|
 \asymp_d\min\{m,\sqrt{m\log(eQ)}\}.
\end{equation}
The same estimate holds for the signed maximum.

\label{thm:affine}
For independent symmetric signs indexed by $\mathbb F_q^d$,
\begin{equation}\label{eq:affine}
 \mathbb E\max_{V\in\mathcal A}\left|\sum_{x\in V}\varepsilon_x\right|
 \asymp\min\!\left\{q^k,\,
 \sqrt{q^k(k+1)(d-k)\log q}\right\}.
\end{equation}
The constants are universal, and the same estimate holds without absolute values.

\label{cor:tails}
Under the preceding assumptions,
\begin{equation}\label{eq:tails}
 \mathbb E\max_{B\in\mathcal A}\sum_{i\in B}Y_i
 \asymp\int_0^\infty\mathcal L_A\bigl(\Psi(1/t)\bigr)\,dt.
\end{equation}
For the absolute maximum, the right-hand side must be augmented by
$\mathbb E\lvert \sum_{i\in A}Y_i\rvert$. If the law is not normalized, apply the formula to $Y/q(1)$ and multiply the resulting estimate by $q(1)$.
